UPDATE qa_conversations
SET title = #{title}, updated_at = NOW()
WHERE id = #{id} AND user_id = #{userId}

UPDATE qa_conversations
SET deleted = 1, updated_at = NOW()
WHERE id = #{id} AND user_id = #{userId}

UPDATE qa_conversations
SET message_count = message_count + 1, last_message_at = #{now}, updated_at = #{now}
WHERE id = #{id}
